    name: "CloudWatch Alerts",
    sourceType: "cloudwatch",
    template: {
        title: {
            literal: JSON.stringify({
                content: [{
                    content: [{
                        attrs: {
                            label: "Payload → Title",
                            missing: false,
                            name: "title",
                        },
                        type: "varSpec",
                    }],
                    type: "paragraph",
                }],
                type: "doc",
            }),
        },
        description: {
            literal: JSON.stringify({
                content: [{
                    content: [{
                        attrs: {
                            label: "Payload → Description",
                            missing: false,
                            name: "description",
                        },
                        type: "varSpec",
                    }],
                    type: "paragraph",
                }],
                type: "doc",
            }),
        },
        attributes: [{
            alertAttributeId: team.id,
            binding: {
                value: {
                    reference: "expressions[\"cloudwatch-team\"]",
                },
                mergeStrategy: "first_wins",
            },
        }],
        expressions: [{
            label: "Team",
            operations: [{
                operationType: "parse",
                parse: {
