incident:index/escalationPath:Escalation.description:
Create and manage escalation paths.

We'd generally recommend building escalation paths in our [web dashboard](https://app.incident.io/~/on-call/escalation-paths), and using the 'Export' flow to generate your Terraform, as it's easier to see what you've configured. You can also make changes to an existing escalation path and copy the resulting Terraform without persisting it.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as incident from "@incident-io/pulumi";

// This is the primary schedule that receives pages in working hours.
const primaryOnCall = new incident.Schedule("primary_on_call", {
    name: "Primary",
    timezone: "Europe/London",
    rotations: [{
        id: "primary",
        name: "Primary",
        versions: [{
            handoverStartAt: "2024-05-01T12:00:00Z",
            users: [],
            layers: [{
                id: "primary",
                name: "Primary",
            }],
            handovers: [{
                intervalType: "daily",
                interval: 1,
            }],
        }],
    }],
});
// If in working hours, send high-urgency alerts. Otherwise use low-urgency.
const urgentSupport = new incident.EscalationPath("urgent_support", {
    name: "Urgent support",
    paths: [{
        id: "start",
        type: "if_else",
        ifElse: {
            conditions: [{
                operation: "is_active",
                paramBindings: [],
                subject: "escalation.working_hours[\"UK\"]",
            }],
            thenPath: [
                {
                    type: "level",
                    level: {
                        targets: [{
                            type: "schedule",
                            id: primaryOnCall.id,
                            urgency: "high",
                        }],
                        timeToAckSeconds: 300,
                    },
                },
                {
                    type: "delay",
                    delay: {
                        delaySeconds: 120,
                    },
                },
                {
                    type: "repeat",
                    repeat: {
                        repeatTimes: 3,
                        toNode: "start",
                    },
                },
            ],
            elsePath: [{
                type: "level",
                level: {
                    targets: [{
                        type: "schedule",
                        id: primaryOnCall.id,
                        urgency: "low",
                    }],
                    timeToAckSeconds: 300,
                },
            }],
        },
    }],
    workingHours: [{
        id: "UK",
        name: "UK",
        timezone: "Europe/London",
        weekdayIntervals: [{
            weekday: "monday",
            startTime: "09:00",
            endTime: "17:00",
        }],
    }],
    teamIds: [
        "01FCNDV6P870EA6S7TK1DSYD00",
        "01FCNDV6P870EA6S7TK1DSYD01",
    ],
});
// A last resort path, which the path below hands over to.
const fallback = new incident.EscalationPath("fallback", {
    name: "Fallback",
    paths: [{
        type: "level",
        level: {
            targets: [{
                type: "schedule",
                id: primaryOnCall.id,
                urgency: "high",
            }],
            timeToAckSeconds: 300,
        },
    }],
});
// If nobody acknowledges here, reassign the escalation to the fallback path. It
// continues from that path's first node rather than ending unacknowledged.
const withReassignment = new incident.EscalationPath("with_reassignment", {
    name: "Support, with a fallback",
    paths: [
        {
            type: "level",
            level: {
                targets: [{
                    type: "schedule",
                    id: primaryOnCall.id,
                    urgency: "low",
                }],
                timeToAckSeconds: 300,
            },
        },
        {
            type: "escalation_path",
            escalationPath: {
                escalationPathId: fallback.id,
            },
        },
    ],
});
