incident:index/getAlertSources:getAlertS.description:
Configure your alert sources in incident.io.

Alert sources are the systems that send alerts to incident.io, which can then be routed to the right people and teams.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as incident from "@incident-io/pulumi";
import * as std from "@pulumi/std";

function canOutput_(
    fn: () => pulumi.Input<any>
): pulumi.Output<boolean> {
    try {
        return pulumi.output(fn()).apply(result => result !== undefined);
    } catch {
        return pulumi.output(false);
    }
}


export = async () => {
    // Example 1: Get all alert sources
    const all = await incident.getAlertSources({});
    // Example 2: Filter by source type
    const webhooksOnly = await incident.getAlertSources({
        sourceType: "http",
    });
    // Example 3: Filter by different source types
    const emailSources = await incident.getAlertSources({
        sourceType: "email",
    });
    const jiraSources = await incident.getAlertSources({
        sourceType: "jira",
    });
    // Group alert sources by type
    const alertSourcesByType = .reduce((__obj, source) => ({ ...__obj, [source.sourceType]: source }), {});
    // Get only webhook sources with specific naming pattern
    const productionWebhooks = .filter(source => 
canOutput_(() => std.regex({
        pattern: "^Production",
        string: source.name,
    }).result)).map(source => (source));
    // Create a map of alert source names to IDs
    const alertSourceNameToId = .reduce((__obj, source) => ({ ...__obj, [source.name]: source.id }), {});
    return {
        allAlertSourceNames: .map(source => (source.name)),
        allAlertSourceIds: .map(source => (source.id)),
        webhookAlertSourcesCount: webhooksOnly.alertSources.length,
        webhookAlertSourceDetails: .map(source => ({
            id: source.id,
            name: source.name,
            sourceType: source.sourceType,
            secretToken: source.secretToken,
        })),
        alertSourcesByType: alertSourcesByType,
        productionWebhookCount: productionWebhooks.length,
        alertSourceLookup: alertSourceNameToId,
    };
}
```
